import {readFileSync,writeFileSync,readdirSync,unlinkSync} from 'node:fs';
import sharp from 'sharp';
const out='/Users/pragadees.xd/Downloads/Ducky Land/concepts/themes/world-map/bigger',dir='public/pixi-art/themes/bog/communities';
const art=JSON.parse(readFileSync('public/pixi-art/themes/bog/art.json')),used=new Set(art.ground.tiles.map(t=>t.src.split('/').at(-1)));
// Remove only obsolete outputs generated by this script family, never source kit files.
for(const f of readdirSync(dir))if((/^ground-\d+-\d+\.png$/.test(f)||/^original-.*\.svg$/.test(f))&&!used.has(f))unlinkSync(dir+'/'+f);
const ref='/Users/pragadees.xd/Downloads/Ducky Land/concepts/themes/world-map/cursor-camp-paths-ref.jpg';
const W=2100,H=750,layers=[];for(const [src,left]of [[ref,0],[out+'/bog-ground-crops/road-junction.png',700],[out+'/bog-ground-crops/lane.png',1400]])layers.push({input:await sharp(src).resize(700,620,{fit:'contain',background:'#F0E1B4'}).png().toBuffer(),left,top:75});
const labels=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><g font-family="Arial" font-size="25" font-weight="bold" fill="#39472D"><text x="30" y="44">Cursor Camp, look reference only</text><text x="730" y="44">Bog road junction</text><text x="1430" y="44">Bog residential lane</text></g><text x="1050" y="730" text-anchor="middle" font-family="Arial" font-size="21" fill="#39472D">Original Bog art. Sandy wear, raised outlined banks, ruts, pebbles and tufts. Full crops: 0.8 px / world unit.</text></svg>`;
layers.push({input:Buffer.from(labels),left:0,top:0});await sharp({create:{width:W,height:H,channels:4,background:'#F0E1B4'}}).composite(layers).png().toFile(out+'/bog-paths-vs-reference.png');
console.log('Proof sheet saved; obsolete generated ground outputs cleaned.');
